let marquee=document.querySelector(".marquee"),marqueeTrack=document.querySelector(".marquee__track"),marqueeGroup=marqueeTrack&&marqueeTrack.querySelector(".marquee__group"),marqueeTimer;function buildMarquee(){if(marquee&&marqueeTrack&&marqueeGroup){marqueeTrack.querySelectorAll(".marquee__group").forEach(function(e,r){0<r&&e.remove()});var e=marqueeGroup.offsetWidth;if(e){var r=Math.max(2,Math.ceil(2.2*marquee.offsetWidth/e)),a=r%2==0?r:r+1;for(let e=1;e<a;e++){var u=marqueeGroup.cloneNode(!0);u.setAttribute("aria-hidden","true"),marqueeTrack.append(u)}r=e*a/2;marqueeTrack.style.setProperty("--marquee-duration",Math.max(32,Math.round(r/45))+"s")}}}function initMarquee(){buildMarquee(),window.addEventListener("load",buildMarquee),window.addEventListener("resize",function(){clearTimeout(marqueeTimer),marqueeTimer=setTimeout(buildMarquee,150)})}export{initMarquee};